try:
    import datetime
    H = ('2026-10-16', '2026-12-25', '2026-12-26', '2027-01-01')
    def bd(x):
        return x.weekday() < 5 and x.isoformat() not in H
    try:
        today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
    except Exception:
        today = datetime.date.today()
    early = today
    n = 0
    while n < 4:
        early += datetime.timedelta(days=1)
        if bd(early):
            n += 1
    late = today + datetime.timedelta(days=2)
    while not bd(late):
        late -= datetime.timedelta(days=1)
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict) and isinstance(d.get('products'), list):
            for p in d['products']:
                if not isinstance(p, dict):
                    continue
                cents = int(round(float(p.get('past_due') or 0) * 100))
                p['floor'] = ((cents * 3 + 5) // 10) / 100.0
                p.pop('minimum_payment', None)
                p.pop('instalment_amount', None)
                if int(p.get('days_late') or 0) <= 10:
                    p['band'] = 'early'
                    p['latest_promise_date'] = early.isoformat()
                else:
                    p['band'] = 'late'
                    p['latest_promise_date'] = late.isoformat()
            d['what_to_do_next'] = 'Name the product and its past_due, and ask when they can pay the full past_due. Do not mention the floor yet.'
        else:
            result['what_to_do_next'] = 'The account could not be loaded. Call get_account once more.'
except Exception:
    pass

